import UIKit

class TrackedVC: UIViewController {
    var events: [String] = []

    override func viewDidLoad() {
        super.viewDidLoad()
        events.append("load")
    }

    override func viewWillAppear(_ animated: Bool) {
        super.viewWillAppear(animated)
        events.append("appear")
    }
}

let tVC = TrackedVC()
_ = tVC.view
tVC.viewWillAppear(false)
print("Events: \(tVC.events.joined(separator: ","))")

import UIKit

class TeardownVC: UIViewController {
    var timerRunning: Bool = true

    override func viewWillDisappear(_ animated: Bool) {
        super.viewWillDisappear(animated)
        timerRunning = false
    }
}

let tdVC = TeardownVC()
tdVC.viewWillDisappear(false)
print("Timer running: \(tdVC.timerRunning)")

import UIKit

class RoundedButtonVC: UIViewController {
    let button = UIButton(frame: CGRect(x: 0, y: 0, width: 100, height: 40))

    override func viewDidLayoutSubviews() {
        super.viewDidLayoutSubviews()
        button.layer.cornerRadius = button.bounds.height / 2
    }
}

let rbVC = RoundedButtonVC()
rbVC.view.addSubview(rbVC.button)
rbVC.viewDidLayoutSubviews()
print("Radius: \(rbVC.button.layer.cornerRadius)")
